// Reset the per-run accumulator used by the loop body.
const sd = $getWorkflowStaticData('global');
sd.queueResults = [];

const cfg = $('Set Validation Rules').first().json;
const expectedPattern = 'yyyy-MM-dd_HHmm__label';
const utcOffsetMinutes = Number(cfg.utcOffsetMinutes || 0);

const folders = $input.all().map(function (item) {
  return item.json;
}).filter(function (folder) {
  return folder && folder.id;
});

const nameRe = /^(\d{4})-(\d{2})-(\d{2})_(\d{2})(\d{2})__(.+)$/;
const now = Date.now();

function isRealDate(y, mo, d, hh, mm) {
  if (mo < 1 || mo > 12) return false;
  if (d < 1 || d > 31) return false;
  if (hh < 0 || hh > 23) return false;
  if (mm < 0 || mm > 59) return false;

  const dt = new Date(Date.UTC(y, mo - 1, d, hh, mm));
  return dt.getUTCFullYear() === y
    && dt.getUTCMonth() + 1 === mo
    && dt.getUTCDate() === d;
}

const parsed = folders.map(function (folder) {
  const match = nameRe.exec(folder.name || '');
  const record = {
    id: folder.id,
    name: folder.name,
    scheduleKey: null,
    scheduledAtUtc: null,
    dateValid: false,
    isFuture: false,
    isDuplicate: false,
    nameReasons: [],
    warnings: [],
  };

  if (!match) {
    record.nameReasons.push('folder name must match ' + expectedPattern);
    return record;
  }

  const y = parseInt(match[1], 10);
  const mo = parseInt(match[2], 10);
  const d = parseInt(match[3], 10);
  const hh = parseInt(match[4], 10);
  const mm = parseInt(match[5], 10);

  if (!isRealDate(y, mo, d, hh, mm)) {
    record.nameReasons.push('folder name contains an invalid date or time');
    return record;
  }

  record.dateValid = true;
  record.scheduleKey = match[1] + '-' + match[2] + '-' + match[3] + '_' + match[4] + match[5];

  // Convert the local time encoded in the folder name to UTC.
  const timestamp = Date.UTC(y, mo - 1, d, hh, mm) - (utcOffsetMinutes * 60 * 1000);
  record.scheduledAtUtc = new Date(timestamp).toISOString();
  record.isFuture = timestamp > now;

  if (!record.isFuture) {
    record.nameReasons.push('scheduled time is not in the future');
  }

  return record;
});

// A duplicate time is a warning, not a hard failure.
const counts = {};
parsed.forEach(function (record) {
  if (record.scheduleKey) {
    counts[record.scheduleKey] = (counts[record.scheduleKey] || 0) + 1;
  }
});

parsed.forEach(function (record) {
  if (record.scheduleKey && counts[record.scheduleKey] > 1) {
    record.isDuplicate = true;
    record.warnings.push('shares its scheduled time with another folder');
  }
});

return parsed.map(function (record) {
  return { json: record };
});

const LF = String.fromCharCode(10);
const sd = $getWorkflowStaticData('global');
const results = (sd.queueResults || []).slice();

const valid = results.filter(function (record) {
  return record.status === 'valid';
});
const warnings = results.filter(function (record) {
  return record.status === 'warning';
});
const invalid = results.filter(function (record) {
  return record.status === 'invalid';
});

const lines = [];
lines.push('GOOGLE DRIVE QUEUE VALIDATION');
lines.push('');
lines.push('Total: ' + results.length);
lines.push('Valid: ' + valid.length);
lines.push('Warnings: ' + warnings.length);
lines.push('Invalid: ' + invalid.length);

if (results.length === 0) {
  lines.push('');
  lines.push('No queue folders were found.');
}

if (invalid.length > 0) {
  lines.push('');
  lines.push('INVALID');
  invalid.forEach(function (record) {
    lines.push(record.name);
    lines.push('Reason: ' + record.reasons.join('; '));
    lines.push('');
  });
}

if (warnings.length > 0) {
  lines.push('WARNINGS');
  warnings.forEach(function (record) {
    lines.push(record.name);
    lines.push('Reason: ' + record.warnings.join('; '));
    lines.push('');
  });
}

if (valid.length > 0) {
  lines.push('VALID');
  valid.forEach(function (record) {
    lines.push(record.name + ' (' + record.imageCount + ' image(s))');
  });
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    summary: {
      valid: valid.length,
      warnings: warnings.length,
      invalid: invalid.length,
      total: results.length,
    },
    report: lines.join(LF),
    results: results,
  },
}];

const cfg = $('Set Validation Rules').first().json;
const supported = (cfg.supportedExtensions || []).map(function (extension) {
  return String(extension).toLowerCase();
});
const maxImages = Number(cfg.maxImages || 4);
const minImages = Number(cfg.minImages || 1);

const folder = $('Loop Through Folders').item.json;

// An empty folder arrives as an empty item because "Always Output Data" is enabled.
const children = $input.all().map(function (item) {
  return item.json;
}).filter(function (child) {
  return child && child.id;
});

const reasons = (folder.nameReasons || []).slice();
const warnings = (folder.warnings || []).slice();

let tweetCount = 0;
let imageCount = 0;
const unsupported = [];
const markers = [];
const nestedFolders = [];

children.forEach(function (child) {
  const name = String(child.name || '');
  const lowerName = name.toLowerCase();
  const isFolder = child.mimeType === 'application/vnd.google-apps.folder';

  if (isFolder) {
    nestedFolders.push(name);
    return;
  }

  if (lowerName === 'tweet.txt') {
    tweetCount++;
    return;
  }

  const isMarker = lowerName.indexOf('receipt') !== -1
    || lowerName.indexOf('posted') !== -1
    || lowerName.indexOf('tweet_id') !== -1
    || lowerName.slice(-5) === '.json';

  if (isMarker) {
    markers.push(name);
    return;
  }

  const extension = lowerName.indexOf('.') !== -1
    ? lowerName.split('.').pop()
    : '';

  if (supported.indexOf(extension) !== -1) {
    imageCount++;
    return;
  }

  unsupported.push(name);
});

if (tweetCount === 0) {
  reasons.push('tweet.txt is missing');
}
if (tweetCount > 1) {
  reasons.push(tweetCount + ' tweet.txt files found; expected exactly 1');
}
if (imageCount < minImages) {
  reasons.push(imageCount + ' images found; minimum is ' + minImages);
}
if (imageCount > maxImages) {
  reasons.push(imageCount + ' images found; maximum is ' + maxImages);
}
if (unsupported.length > 0) {
  reasons.push('unsupported files: ' + unsupported.join(', '));
}
if (nestedFolders.length > 0) {
  reasons.push('nested folders are not allowed: ' + nestedFolders.join(', '));
}
if (markers.length > 0) {
  reasons.push('folder appears already processed: ' + markers.join(', '));
}

let status = 'valid';
if (reasons.length > 0) {
  status = 'invalid';
} else if (warnings.length > 0) {
  status = 'warning';
}

const record = {
  name: folder.name,
  id: folder.id,
  scheduledAtUtc: folder.scheduledAtUtc || null,
  status: status,
  reasons: reasons,
  warnings: warnings,
  tweetCount: tweetCount,
  imageCount: imageCount,
};

const sd = $getWorkflowStaticData('global');
if (!sd.queueResults) {
  sd.queueResults = [];
}
sd.queueResults.push(record);

return [{ json: record }];
